function publicCalculator(path){
 const slug=path.split('/')[2]||'';
 const localNow=new Date(),todayLocal=`${localNow.getFullYear()}-${String(localNow.getMonth()+1).padStart(2,'0')}-${String(localNow.getDate()).padStart(2,'0')}`;
 const items={petrol:['Petrol cost calculator','Plan fuel spend before you set off.'],mileage:['Mileage calculator','Measure real-world fuel efficiency from a fill-up.'],age:['Age calculator','Your exact age, down to the second.'],bmi:['BMI calculator','Understand your body mass index with useful context.']};
 if(!items[slug])return `${publicHeader()}<main class="public-calc-wrap"><div class="public-kicker">ATELIER / EVERYDAY TOOLS</div><h1 class="serif">Calculators, made <em>clear.</em></h1><p>Thoughtful, practical calculators for everyday decisions. No sign-in required.</p><div class="public-tool-grid">${Object.entries(items).map(([k,v],i)=>`<a class="public-tool-card" href="/calculators/${k}" data-link><span class="public-tool-number">0${i+1}</span><div><b>${v[0]}</b><small>${v[1]}</small></div><span class="public-tool-arrow">↗</span></a>`).join('')}</div></main>`;
 let [title,desc]=items[slug],fields='';
 if(slug==='petrol')fields=`<div class="calc-field-grid"><label>Journey distance <span><input id="pubDistance" type="number" min="0.1" step="0.1" value="100"><i>km</i></span></label><label>Vehicle mileage <span><input id="pubMileage" type="number" min="0.1" step="0.1" value="40"><i>km/L</i></span></label><label>Petrol price <span><i>₹</i><input id="pubPrice" type="number" min="0" step="0.01" value="100"></span></label><label>Round trip <select id="pubRound"><option value="1">One way</option><option value="2">Return journey</option></select></label></div><p class="calc-hint">Use your vehicle's average mileage and the current price per litre for a closer estimate.</p>`;
 else if(slug==='mileage')fields=`<div class="calc-field-grid"><label>Distance travelled <span><input id="pubDistance" type="number" min="0.1" step="0.1" placeholder="e.g. 425"><i>km</i></span></label><label>Fuel filled <span><input id="pubFuel" type="number" min="0.01" step="0.01" placeholder="e.g. 12.5"><i>litres</i></span></label><label>Fuel price (optional) <span><i>₹</i><input id="pubPrice" type="number" min="0" step="0.01" placeholder="per litre"></span></label></div><p class="calc-hint">For best accuracy, record distance between full-tank fill-ups and the exact litres needed to refill.</p>`;
 else if(slug==='age')fields=`<div class="calc-field-grid"><label>Date of birth <input id="pubDob" type="date" max="${todayLocal}" required></label><label>Time of birth <input id="pubBirthTime" type="time" step="1" value="00:00:00"></label><label>Calculate as of <input id="pubAsOf" type="date" value="${todayLocal}"></label><label>Current time <input id="pubAsOfTime" type="time" step="1" value="${localNow.toTimeString().slice(0,8)}"></label></div><p class="calc-hint">Enter seconds if known. Turn on the live clock to keep the seconds display moving.</p><label class="calc-live-toggle"><input id="pubLiveAge" type="checkbox" checked> Keep current time live (HH:MM:SS)</label>`;
 else fields=`<div class="calc-field-grid"><label>Height <span><input id="pubHeight" type="number" min="1" step="0.1" placeholder="e.g. 175"><i>cm</i></span></label><label>Weight <span><input id="pubWeight" type="number" min="1" step="0.1" placeholder="e.g. 72"><i>kg</i></span></label></div><p class="calc-hint">BMI is a screening measure for adults, not a diagnosis. It does not distinguish muscle from body fat.</p>`;
 return `${publicHeader()}<main class="public-calc-wrap"><div class="public-breadcrumb"><a href="/calculators" data-link>Calculators</a><span>/</span>${title}</div><div class="public-calc-intro"><div class="public-kicker">ATELIER / CALCULATOR ${slug.toUpperCase()}</div><h1 class="serif">${title.replace(' calculator','')} <em>calculator.</em></h1><p>${desc}</p></div><section class="public-calc-layout"><div class="panel public-calc-panel"><div class="calc-panel-heading"><span class="calc-panel-icon">${slug==='petrol'?'₹':slug==='mileage'?'↗':slug==='age'?'◷':'◎'}</span><div><h2>Your details</h2><small>Enter the values below to calculate.</small></div></div>${fields}<button class="btn" id="publicCalculate">Calculate result <span>↗</span></button></div></section><section class="public-result-section"><div class="result-heading"><span>YOUR RESULT</span><small id="publicResultMeta">Ready when you are</small></div><div class="public-calc-result" id="publicCalcResult" aria-live="polite">Your result will appear here.</div></section><div class="converter-back"><a href="/calculators" data-link>← All calculators</a></div></main>`;
}
